import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, CORE_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('explicit !!int with unsigned octal resolves', () => {
    assert.strictEqual(load('!!int "0o17"', { schema: CORE_SCHEMA }), 15);
    assert.strictEqual(load('0o17', { schema: CORE_SCHEMA }), 15);
  });
});

